273	
274	// 创建被服务拒绝：页面显示服务返回的具体原因，保留已填内容，
275	// 不显示成功提示、不向列表添加记录；用户可直接修改保留的内容再提交。
276	test('创建被拒绝：显示服务端原因、保留已填内容、列表不变，可直接修改后再提交', { timeout: 60000 }, async (t) => {
277	  const { page } = await setupPage(t);
278	  const initialRows = await readRows(page);
279	  assertSeedRows(initialRows);
280	
281	  // 第一次创建请求被“服务”拒绝并返回具体原因；其余请求（含重试）正常放行。
282	  const REASON = '服务端拒绝：房间数量已达本场赛事上限';
283	  let rejected = 0;
284	  await page.setRequestInterception(true);
285	  page.on('request', (req) => {
286	    if (req.method() === 'POST' && req.url().endsWith('/api/rooms') && rejected === 0) {
287	      rejected++;
288	      req.respond({
289	        status: 400,
290	        contentType: 'application/json; charset=utf-8',
291	        body: JSON.stringify({ error: REASON }),
292	      });
293	    } else {
294	      req.continue();
295	    }
296	  });
297	
298	  const rawName = '  深夜 飞行棋 挑战赛  ';
299	  await page.type('#name', rawName);
300	  await page.select('#game', 'ludo');
301	  await page.select('#capacity', '3');
302	  await page.type('#turnSeconds', '60');
303	  await page.click('#submit');
304	
305	  // 页面显示服务返回的具体原因，不显示成功提示。
306	  await waitForMessageKind(page, 'error');
307	  const msg = await readMessage(page);
308	  assert.equal(msg.text, REASON, '应原样显示服务返回的拒绝原因');
309	  assert.ok(!msg.className.includes('ok'), '被拒绝时不应显示成功提示');
310	  assert.ok(!msg.text.includes('已创建'), '被拒绝时不应出现成功文案');
311	
312	  // 已填写的名称、规则、人数、时间全部保留，用户不必重新填写。
313	  assert.deepEqual(await readFormState(page), {
314	    name: rawName,
315	    game: 'ludo',
316	    capacity: '3',
317	    capacityDisabled: false,
318	    turnSeconds: '60',
319	    submitDisabled: false,
320	  }, '被拒绝后应保留已填写内容并恢复按钮可用');
321	
322	  // 列表不添加本次房间，原有房间内容与次序不变。
323	  assert.deepEqual(await readRows(page), initialRows, '被拒绝时不应改动房间列表');
324	
325	  // 用户只修改名称（其余字段保留）即可再次提交，本次放行到真实服务。
326	  await page.$eval('#name', (el) => { el.value = ''; });
327	  const newName = '改后的 飞行棋 房间';
328	  await page.type('#name', newName);
329	  await page.click('#submit');
330	
331	  await waitForMessageKind(page, 'ok');
332	  const msg2 = await readMessage(page);
333	  assert.ok(msg2.text.startsWith(SUCCESS_PREFIX), `重试应成功，实际提示: ${msg2.text}`);
334	
335	  // 新记录使用保留的规则、人数与时间，追加在原有房间之后。
336	  await waitForRowCount(page, 3);
337	  const rows = await readRows(page);
338	  assert.deepEqual(rows.slice(0, 2), initialRows, '原有房间的内容或次序被改变');
339	  const added = rows[2];
340	  assert.equal(added.cells[1], newName, '重试时保留后修改的名称应生效');
341	  assert.equal(added.cells[2], '飞行棋', '重试应沿用保留的游戏规则');
342	  assert.equal(added.cells[3], '3 人', '重试应沿用保留的人数上限');
343	  assert.equal(added.cells[4], '60 秒', '重试应沿用保留的时间限制');
344	  assert.equal(added.badge, '未开始');
345	  assert.equal((await readFormState(page)).submitDisabled, false, '重试完成后按钮应恢复可用');
346	});
347	
348	// 创建已成功、仅列表刷新失败：成功提示与编号保留，表单按成功处理；
349	// 列表区域明确显示加载失败，不得显示“还没有房间记录”，也不得把创建说成失败。
350	test('创建成功但列表刷新失败：保留成功提示与编号，列表区域显示加载失败', { timeout: 60000 }, async (t) => {
351	  const { page, baseURL } = await setupPage(t);
352	
353	  // 放行创建请求，仅让紧随其后的列表读取失败。
354	  await page.setRequestInterception(true);
355	  page.on('request', (req) => {
356	    if (req.method() === 'GET' && req.url().endsWith('/api/rooms')) {
357	      req.respond({
358	        status: 500,
359	        contentType: 'application/json; charset=utf-8',
360	        body: JSON.stringify({ error: '模拟列表读取失败' }),
361	      });
362	    } else {
363	      req.continue();
364	    }
365	  });
366	
367	  await fillGomokuForm(page, '  周末 五子棋 友谊赛  ', 0);
368	  await page.click('#submit');
369	
370	  // 创建成功提示与编号仍然展示。
371	  await waitForMessageKind(page, 'ok');
372	  const msg = await readMessage(page);
373	  assert.ok(msg.text.startsWith(SUCCESS_PREFIX), `应保留创建成功提示，实际: ${msg.text}`);
374	  const shownId = msg.text.slice(SUCCESS_PREFIX.length);
375	  assert.ok(shownId, '成功提示中应包含新房间编号');
376	
377	  // 表单仍按成功处理（恢复初始填写状态）。
378	  const form = await readFormState(page);
379	  assert.deepEqual(form, {
380	    name: '',
381	    game: '',
382	    capacity: '',
383	    capacityDisabled: true,
384	    turnSeconds: '',
385	    submitDisabled: false,
386	  }, '列表刷新失败不应影响已成功创建的表单处理与按钮恢复');
387	
388	  // 列表区域明确显示加载失败，而不是空列表提示或旧内容。
389	  await page.waitForFunction(
390	    () => !!document.querySelector('#list-area .list-error'),
391	    { timeout: 10000 },
392	  );
393	  const list = await readListArea(page);
394	  assert.equal(list.errorText, '房间列表加载失败，请稍后刷新重试。已有数据不会因此丢失。');
395	  assert.equal(list.emptyText, null, '列表刷新失败时不得显示“还没有房间记录”');
396	  assert.ok(!list.text.includes('还没有房间记录'), '列表刷新失败时不得显示空列表文案');
397	  assert.ok(!list.hasTable, '列表刷新失败时不应展示旧表格冒充最新列表');
398	
399	  // 成功提示不被覆盖为失败：创建没有被说成失败，用户无需再次创建。
400	  const msgAfter = await readMessage(page);
401	  assert.ok(msgAfter.className.includes('ok'), '列表刷新失败不应把已完成的创建说成失败');
402	  assert.equal(msgAfter.text, msg.text, '成功提示与编号应保留');
403	
404	  // 服务端确实已保存本次创建（证明创建本身成功，只是刷新失败）。
405	  const res = await fetch(baseURL + '/api/rooms');
406	  assert.equal(res.status, 200);
407	  const data = await res.json();
408	  assert.equal(data.rooms.length, 3, '服务端应已保存新房间');
409	  assert.equal(data.rooms[2].id, shownId, '服务端保存的编号应与页面提示一致');
410	});
411	
412	// 提交等待期间创建按钮暂时不可用，请求完成后恢复可用，页面不停在等待状态。
413	test('提交等待期间创建按钮不可用，请求完成后恢复', { timeout: 60000 }, async (t) => {
414	  const { page } = await setupPage(t);
415	
416	  // 挂起创建请求，直到测试手动放行，以观察等待期间的按钮状态。
417	  await page.setRequestInterception(true);
418	  let releasePost;
419	  const postHeld = new Promise((resolve) => { releasePost = resolve; });
420	  page.on('request', (req) => {
421	    if (req.method() === 'POST' && req.url().endsWith('/api/rooms')) {
422	      postHeld.then(() => req.continue());
423	    } else {
424	      req.continue();
425	    }
426	  });
427	
428	  await fillGomokuForm(page, '等待中的房间', 0);
429	  await page.click('#submit');
430	
431	  // 等待期间按钮不可用，且不是瞬间恢复。
432	  await page.waitForFunction(
433	    () => document.getElementById('submit').disabled,
434	    { timeout: 5000 },
435	  );
436	  await new Promise((resolve) => setTimeout(resolve, 300));
437	  assert.equal((await readFormState(page)).submitDisabled, true, '提交等待期间按钮应保持不可用');
438	
439	  // 放行请求：完整成功后按钮恢复可用，不停在等待状态。
440	  releasePost();
441	  await waitForMessageKind(page, 'ok');
442	  await waitForRowCount(page, 3);
443	  await page.waitForFunction(
444	    () => !document.getElementById('submit').disabled,
445	    { timeout: 10000 },
446	  );
447	  assert.equal((await readFormState(page)).submitDisabled, false, '完成后按钮应恢复可用');
448	});
